PRAGMA foreign_keys = ON;
CREATE TABLE organizations(id TEXT PRIMARY KEY, name TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('simulation','production')), created_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE memberships(organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('admin','member','viewer')), created_at TEXT NOT NULL, PRIMARY KEY(organization_id,user_id));
CREATE TABLE documents(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, sha256 TEXT NOT NULL, size INTEGER NOT NULL CHECK(size>0), pages INTEGER NOT NULL CHECK(pages>=0 AND (status<>'ready' OR pages>0)), status TEXT NOT NULL CHECK(status IN ('ready','quarantined','rejected','purged')), source TEXT NOT NULL CHECK(source IN ('import','render')), storage_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(organization_id,id), UNIQUE(organization_id,sha256));
CREATE TABLE senders(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), channel TEXT NOT NULL CHECK(channel IN ('fax','email','postal')), name TEXT NOT NULL, address TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('verified','pending','disabled')), mode TEXT NOT NULL CHECK(mode IN ('simulation','production')), created_at TEXT NOT NULL, UNIQUE(organization_id,id));
CREATE TABLE campaigns(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','frozen','completed')), manifest_hash TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,id));
CREATE TABLE dispatches(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), campaign_id TEXT, channel TEXT NOT NULL CHECK(channel IN ('fax','email','postal')), recipient_json TEXT NOT NULL CHECK(json_valid(recipient_json)), document_id TEXT, sender_id TEXT, sender_address TEXT NOT NULL, subject TEXT, html TEXT, text TEXT, options_json TEXT NOT NULL CHECK(json_valid(options_json)), status TEXT NOT NULL CHECK(status IN ('prepared','queued','submitting','submission_unknown','accepted','delivered','failed','cancelled','bounced','complained','printed','handed_to_post')), mode TEXT NOT NULL CHECK(mode IN ('simulation','production')), estimated_minor INTEGER NOT NULL CHECK(estimated_minor>=0), ceiling_minor INTEGER NOT NULL CHECK(ceiling_minor>=estimated_minor), known_minor INTEGER CHECK(known_minor>=0), currency TEXT NOT NULL CHECK(currency='EUR'), fingerprint TEXT NOT NULL, prepare_key TEXT NOT NULL, request_hash TEXT NOT NULL, provider TEXT, provider_id TEXT, lease_until TEXT, active_attempt_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(organization_id,id), UNIQUE(organization_id,prepare_key), FOREIGN KEY(organization_id,document_id) REFERENCES documents(organization_id,id), FOREIGN KEY(organization_id,sender_id) REFERENCES senders(organization_id,id), FOREIGN KEY(organization_id,campaign_id) REFERENCES campaigns(organization_id,id));
CREATE INDEX dispatches_org_page ON dispatches(organization_id,created_at DESC,id DESC);
CREATE INDEX dispatches_campaign ON dispatches(organization_id,campaign_id,id);
CREATE INDEX dispatches_reconcile ON dispatches(status,lease_until,id);
CREATE UNIQUE INDEX dispatches_provider_id ON dispatches(provider,provider_id) WHERE provider_id IS NOT NULL;
CREATE TABLE approvals(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, dispatch_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), fingerprint TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(organization_id,dispatch_id), FOREIGN KEY(organization_id,dispatch_id) REFERENCES dispatches(organization_id,id));
CREATE TABLE idempotency_keys(organization_id TEXT NOT NULL REFERENCES organizations(id), operation TEXT NOT NULL, key TEXT NOT NULL, request_hash TEXT NOT NULL, resource_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(organization_id,operation,key));
CREATE TABLE usage(organization_id TEXT NOT NULL REFERENCES organizations(id), channel TEXT NOT NULL, period TEXT NOT NULL, limit_count INTEGER NOT NULL CHECK(limit_count>=0), reserved_count INTEGER NOT NULL DEFAULT 0 CHECK(reserved_count>=0), confirmed_count INTEGER NOT NULL DEFAULT 0 CHECK(confirmed_count>=0), limit_minor INTEGER NOT NULL CHECK(limit_minor>=0), reserved_minor INTEGER NOT NULL DEFAULT 0 CHECK(reserved_minor>=0), confirmed_minor INTEGER NOT NULL DEFAULT 0 CHECK(confirmed_minor>=0), currency TEXT NOT NULL CHECK(currency='EUR'), PRIMARY KEY(organization_id,channel,period), CHECK(reserved_count+confirmed_count<=limit_count), CHECK(reserved_minor+confirmed_minor<=limit_minor));
CREATE TABLE reservations(dispatch_id TEXT PRIMARY KEY REFERENCES dispatches(id), organization_id TEXT NOT NULL, channel TEXT NOT NULL, period TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor>=0), status TEXT NOT NULL CHECK(status IN ('reserved','confirmed','released')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(organization_id,channel,period) REFERENCES usage(organization_id,channel,period));
CREATE TABLE outbox(id TEXT PRIMARY KEY, dispatch_id TEXT NOT NULL UNIQUE REFERENCES dispatches(id), organization_id TEXT NOT NULL REFERENCES organizations(id), status TEXT NOT NULL CHECK(status IN ('pending','published')), created_at TEXT NOT NULL, published_at TEXT);
CREATE INDEX outbox_pending ON outbox(status,created_at,id);
CREATE TABLE attempts(id TEXT PRIMARY KEY, dispatch_id TEXT NOT NULL REFERENCES dispatches(id), organization_id TEXT NOT NULL REFERENCES organizations(id), provider TEXT NOT NULL, provider_id TEXT, status TEXT NOT NULL CHECK(status IN ('started','accepted','rejected','unknown')), error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX attempts_dispatch ON attempts(organization_id,dispatch_id,created_at);
CREATE TABLE provider_events(id TEXT PRIMARY KEY, provider TEXT NOT NULL, provider_event_id TEXT NOT NULL, provider_id TEXT, dispatch_id TEXT REFERENCES dispatches(id), organization_id TEXT REFERENCES organizations(id), kind TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), occurred_at TEXT NOT NULL, received_at TEXT NOT NULL, applied_at TEXT, UNIQUE(provider,provider_event_id));
CREATE INDEX events_orphan ON provider_events(provider,provider_id,applied_at);
CREATE INDEX events_dispatch ON provider_events(organization_id,dispatch_id,occurred_at);
CREATE TABLE suppressions(organization_id TEXT NOT NULL REFERENCES organizations(id), email TEXT NOT NULL, reason TEXT NOT NULL CHECK(reason IN ('hard_bounce','complaint','unsubscribe')), created_at TEXT NOT NULL, PRIMARY KEY(organization_id,email));
CREATE TABLE audit_log(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT, action TEXT NOT NULL, resource_id TEXT NOT NULL, details_json TEXT NOT NULL CHECK(json_valid(details_json)), created_at TEXT NOT NULL);
CREATE INDEX audit_org ON audit_log(organization_id,created_at DESC,id);
CREATE TABLE channel_controls(organization_id TEXT NOT NULL REFERENCES organizations(id), channel TEXT NOT NULL, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), PRIMARY KEY(organization_id,channel));
CREATE TRIGGER immutable_document BEFORE UPDATE ON documents WHEN NEW.organization_id<>OLD.organization_id OR NEW.sha256<>OLD.sha256 OR NEW.storage_key<>OLD.storage_key OR NEW.size<>OLD.size OR (NEW.pages<>OLD.pages AND NOT(OLD.status='quarantined' AND OLD.pages=0 AND NEW.status='ready' AND NEW.pages>0)) OR NEW.source<>OLD.source BEGIN SELECT RAISE(ABORT,'immutable_document'); END;
CREATE TRIGGER immutable_dispatch BEFORE UPDATE ON dispatches WHEN NEW.organization_id<>OLD.organization_id OR NEW.channel<>OLD.channel OR NEW.recipient_json<>OLD.recipient_json OR NEW.document_id IS NOT OLD.document_id OR NEW.sender_id IS NOT OLD.sender_id OR NEW.sender_address<>OLD.sender_address OR NEW.subject IS NOT OLD.subject OR NEW.html IS NOT OLD.html OR NEW.text IS NOT OLD.text OR NEW.options_json<>OLD.options_json OR NEW.fingerprint<>OLD.fingerprint OR NEW.estimated_minor<>OLD.estimated_minor OR NEW.ceiling_minor<>OLD.ceiling_minor OR NEW.currency<>OLD.currency OR NEW.campaign_id IS NOT OLD.campaign_id OR NEW.mode<>OLD.mode BEGIN SELECT RAISE(ABORT,'immutable_dispatch'); END;
CREATE TRIGGER frozen_campaign BEFORE INSERT ON dispatches WHEN NEW.campaign_id IS NOT NULL AND EXISTS(SELECT 1 FROM campaigns WHERE id=NEW.campaign_id AND status<>'draft') BEGIN SELECT RAISE(ABORT,'campaign_frozen'); END;
CREATE TRIGGER accept_dispatch BEFORE UPDATE OF status ON dispatches WHEN OLD.status='prepared' AND NEW.status='queued' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM approvals WHERE organization_id=NEW.organization_id AND dispatch_id=NEW.id AND fingerprint=NEW.fingerprint AND expires_at>NEW.updated_at) THEN RAISE(ABORT,'approval_required') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM channel_controls WHERE organization_id=NEW.organization_id AND channel=NEW.channel AND enabled=1) THEN RAISE(ABORT,'channel_disabled') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM usage WHERE organization_id=NEW.organization_id AND channel=NEW.channel AND period=substr(NEW.updated_at,1,7) AND reserved_count+confirmed_count+1<=limit_count AND reserved_minor+confirmed_minor+NEW.ceiling_minor<=limit_minor) THEN RAISE(ABORT,'quota_exceeded') END;
 UPDATE usage SET reserved_count=reserved_count+1,reserved_minor=reserved_minor+NEW.ceiling_minor WHERE organization_id=NEW.organization_id AND channel=NEW.channel AND period=substr(NEW.updated_at,1,7);
 INSERT INTO reservations(dispatch_id,organization_id,channel,period,amount_minor,status,created_at,updated_at) VALUES(NEW.id,NEW.organization_id,NEW.channel,substr(NEW.updated_at,1,7),NEW.ceiling_minor,'reserved',NEW.updated_at,NEW.updated_at);
 INSERT INTO outbox(id,dispatch_id,organization_id,status,created_at) VALUES('outbox_'||NEW.id,NEW.id,NEW.organization_id,'pending',NEW.updated_at);
END;
CREATE TRIGGER confirm_reservation AFTER UPDATE OF status ON dispatches WHEN NEW.status IN ('accepted','delivered','printed','handed_to_post','bounced','complained') AND EXISTS(SELECT 1 FROM reservations WHERE dispatch_id=NEW.id AND status='reserved') BEGIN
 UPDATE usage SET reserved_count=reserved_count-1,reserved_minor=reserved_minor-(SELECT amount_minor FROM reservations WHERE dispatch_id=NEW.id),confirmed_count=confirmed_count+1,confirmed_minor=confirmed_minor+(SELECT amount_minor FROM reservations WHERE dispatch_id=NEW.id) WHERE organization_id=NEW.organization_id AND channel=NEW.channel AND period=(SELECT period FROM reservations WHERE dispatch_id=NEW.id);
 UPDATE reservations SET status='confirmed',updated_at=NEW.updated_at WHERE dispatch_id=NEW.id AND status='reserved';
END;
CREATE TRIGGER release_reservation AFTER UPDATE OF status ON dispatches WHEN NEW.status IN ('cancelled','failed') AND EXISTS(SELECT 1 FROM reservations WHERE dispatch_id=NEW.id AND status='reserved') BEGIN
 UPDATE usage SET reserved_count=reserved_count-1,reserved_minor=reserved_minor-(SELECT amount_minor FROM reservations WHERE dispatch_id=NEW.id),confirmed_count=confirmed_count,confirmed_minor=confirmed_minor WHERE organization_id=NEW.organization_id AND channel=NEW.channel AND period=(SELECT period FROM reservations WHERE dispatch_id=NEW.id);
 UPDATE reservations SET status='released',updated_at=NEW.updated_at WHERE dispatch_id=NEW.id AND status='reserved';
END;
